import{_ as n,a0 as r,w as p,s as u,ao as l,I as s,x as i,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"在 Linux 的 VirtualBox 中從 USB 驅動器啓動 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 的 VirtualBox 中從 USB 驅動器啓動 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 的 VirtualBox 中從 USB 驅動器啓動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 的 VirtualBox 中從 USB 驅動器啓動 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230904 Boot From a USB Drive in VirtualBox in Linux","title":"在 Linux 的 VirtualBox 中從 USB 驅動器啓動","tag":"202309","desc":""},"relativePath":"202309/20230904 Boot From a USB Drive in VirtualBox in Linux.md","filePath":"[post].md"}'),d={name:"202309/20230904 Boot From a USB Drive in VirtualBox in Linux.md"};function m(g,t,b,k,h,x){const e=r("Link");return p(),u("div",null,[t[26]||(t[26]=l('<h1 id="在-linux-的-virtualbox-中從-usb-驅動器啓動" tabindex="-1">在 Linux 的 VirtualBox 中從 USB 驅動器啓動 <a class="header-anchor" href="#在-linux-的-virtualbox-中從-usb-驅動器啓動" aria-label="Permalink to “在 Linux 的 VirtualBox 中從 USB 驅動器啓動”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/22/101826lcduo6etry9ep2rb.jpg" alt=""></p><blockquote><p>你可以在 VirtualBox 中的虛擬機上使用立付 Linux USB。這樣可以省去重新啓動主機的麻煩。</p></blockquote><p>你有一個 <ruby>立付<rt>Live</rt></ruby> Linux USB 嗎？在當前系統上測試它的常用方法是重新啓動，並在系統重新啓動時選擇從立付 USB 啓動。</p><p>但這很煩人，因為你需要停止計算機上的工作並重新啓動它。</p><p>一種干擾較小的方法是使用虛擬機。</p><p>是的，你可以使用 VirtualBox 從虛擬機中的 USB 啓動。這樣，你不必為了嘗試而在 VM 中安裝發行版，而是改用立付會話。</p><p>在本教程中，我將展示在 Linux 系統使用 VirtualBox 從 USB 驅動器啓動的步驟。這需要花費一些時間和精力，但可以讓你免於重啓系統。</p><h3 id="在-linux-的-virtualbox-中從-usb-驅動器啓動-1" tabindex="-1">在 Linux 的 VirtualBox 中從 USB 驅動器啓動 <a class="header-anchor" href="#在-linux-的-virtualbox-中從-usb-驅動器啓動-1" aria-label="Permalink to “在 Linux 的 VirtualBox 中從 USB 驅動器啓動”">​</a></h3><p>由於這是針對高級用户的教程，因此我省略了你事先需要的幾個步驟：</p>',10)),s("ul",null,[s("li",null,[t[1]||(t[1]=i("在 Linux 系統上 ",-1)),o(e,{href:"https://itsfoss.com/install-virtualbox-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[i("安裝 VirtualBox",-1)])]),_:1})]),s("li",null,[t[3]||(t[3]=i("創建立付 Linux USB，最好 ",-1)),o(e,{href:"https://itsfoss.com/use-ventoy/"},{default:a(()=>[...t[2]||(t[2]=[i("使用 Ventoy",-1)])]),_:1})])]),t[27]||(t[27]=s("p",null,"本指南分為三個部分：",-1)),t[28]||(t[28]=s("ul",null,[s("li",null,"創建虛擬機磁盤文件"),s("li",null,"在 VM 中使用 USB 啓動"),s("li",null,"刪除虛擬機磁盤（可選）")],-1)),t[29]||(t[29]=s("p",null,"那麼讓我們從第一個開始。",-1)),t[30]||(t[30]=s("h4",{id:"步驟-1-創建虛擬機磁盤文件-vmdk",tabindex:"-1"},[i("步驟 1：創建虛擬機磁盤文件（VMDK） "),s("a",{class:"header-anchor",href:"#步驟-1-創建虛擬機磁盤文件-vmdk","aria-label":"Permalink to “步驟 1：創建虛擬機磁盤文件（VMDK）”"},"​")],-1)),s("p",null,[t[5]||(t[5]=i("首先，你需要識別 USB 驅動器的磁盤名稱，為此，你需要 ",-1)),o(e,{href:"https://linuxhandbook.com/linux-list-disks/"},{default:a(()=>[...t[4]||(t[4]=[i("列出系統的驅動器",-1)])]),_:1}),t[6]||(t[6]=i("。",-1))]),t[31]||(t[31]=l('<p>為此，我將使用 lsblk 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsblk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/list-drives-in-Linux.png" alt=""></p><blockquote><p>🚧 確保使用不帶任何數字的磁盤名稱。就我而言，Ventoy 以 sdb1 命名，但我仍然只能使用 sdb。</p></blockquote><p>從上圖中，你可以看到，Ventoy 列出了 <code>sdb11</code>，但你必須使用不帶任何數字的名稱。這意味着我必須只使用 <code>sdb</code>，否則，它會拋出錯誤。</p><p>找到驅動器名稱後，使用以下命令中的 <code>VBoxManage</code> 命令來創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo VBoxManage createmedium disk --filename=/path/to/rawdisk.vmdk --variant=RawDisk --format=VMDK --property RawDrive=/dev/sda</span></span></code></pre></div><p>在上面的命令中，將 <code>/path/to/rawdisk.vmdk</code> 替換為要保存文件的路徑 ，將 <code>/dev/sda</code> 替換為目標驅動器。</p><p>就我而言，我想在我的主目錄中創建一個名為 <code>IF.vmdk</code> 的文件，並且我的目標驅動器是 <code>/dev/sdb</code>，然後，我將使用以下命令：</p><blockquote><p>📋 你需要提供絕對路徑來創建 vmdk 文件！</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo VBoxManage createmedium disk --filename=/home/sagar/IF.vmdk --variant=RawDisk --format=VMDK --property RawDrive=/dev/sdb</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/create-virtual-machine-disk-drive-for-virtualbox-to-boot-from-USB-drive-in-Linux.png" alt=""></p><p>最後，使用 <code>chmod</code> 命令更改權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod 777 Filename.vmdk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/use-chmod-command-to-change-the-permissions.png" alt=""></p><h4 id="步驟-2-在-linux-的-virtualbox-中從-usb-啓動" tabindex="-1">步驟 2：在 Linux 的 VirtualBox 中從 USB 啓動 <a class="header-anchor" href="#步驟-2-在-linux-的-virtualbox-中從-usb-啓動" aria-label="Permalink to “步驟 2：在 Linux 的 VirtualBox 中從 USB 啓動”">​</a></h4><p>首先，從系統菜單中打開 VirtualBox，然後單擊 “<ruby>新建<rt>New</rt></ruby>” 按鈕。</p><p>在那裏，為你的虛擬機命名並選擇操作系統類型及其版本：</p><p><img src="https://itsfoss.com/content/images/2023/07/Create-VM-in-VirtualBox-to-boot-from-USB-in-Linux.png" alt=""></p><p>現在，單擊 “<ruby>下一步<rt>Next</rt></ruby>” 按鈕，它會要求你為虛擬機分配硬件資源：</p><p><img src="https://itsfoss.com/content/images/2023/07/allocate-RAM-and-cores-to-Vm-to-boot-from-USB-in-VirtualBox-in-Linux.png" alt=""></p><p>完成硬件資源分配後，單擊“下一步”按鈕。</p><p>在這裏，你將找到創建或添加虛擬磁盤的選項。現在，請執行 3 個簡單步驟：</p><ul><li>選擇第二個選項 “<ruby>使用現有虛擬硬盤文件<rt>Use an Existing Virtual Hard Disk File</rt></ruby>”。</li><li>點擊“文件”圖標。</li><li>點擊“<ruby>添加<rt>Add</rt></ruby>”按鈕並選擇你最近創建的以 <code>.vmdk</code> 結尾的文件。</li></ul><p><img src="https://itsfoss.com/content/images/2023/07/add-virtual-machine-disk-drive-in-VirtualBox-to-boot-from-USB-in-Linux.png" alt=""></p><p>選擇文件後，它將顯示文件的名稱，選擇它並點擊 “<ruby>選擇<rt>Choose</rt></ruby>” 選項：</p><p><img src="https://itsfoss.com/content/images/2023/07/select-the-vmdk-file.png" alt=""></p><p>它將向你顯示已選擇從中啓動的文件。單擊下一步，它將顯示你所做的選擇的摘要。</p><p>點擊 “<ruby>完成<rt>Finish</rt></ruby>” 按鈕：</p><p><img src="https://itsfoss.com/content/images/2023/07/Finish-the-VM-creation-to-boot-from-USB-in-VirtualBox-in-Linux.png" alt=""></p><p>就是這樣！ 虛擬機已創建。</p><p>要啓動虛擬機，首先選擇虛擬機並單擊啓動按鈕：</p><p><img src="https://itsfoss.com/content/images/2023/07/start-the-VM.png" alt=""></p><p>由於我的 USB 有 Ventoy，你可以看到，此處列出了多個發行版：</p><p><img src="https://itsfoss.com/content/images/2023/07/Boot-from-USB-in-VirtualBox-in-Linux.png" alt=""></p><p>很酷。是麼？</p><h4 id="步驟-3-使用刪除虛擬機及-vmdk-文件-可選" tabindex="-1">步驟 3：使用刪除虛擬機及 vmdk 文件（可選） <a class="header-anchor" href="#步驟-3-使用刪除虛擬機及-vmdk-文件-可選" aria-label="Permalink to “步驟 3：使用刪除虛擬機及 vmdk 文件（可選）”">​</a></h4><p>當我在刪除虛擬機後嘗試刪除 vmdk 文件時，當然，它被刪除了，但每當我嘗試創建具有相同名稱的新文件時，它都會給我一個錯誤，説該文件已經存在！</p><p>因此，在這裏，我將引導你瞭解如何刪除虛擬機及 vmdk 文件。</p><p>首先，關閉虛擬機並將其刪除。</p><p><img src="https://itsfoss.com/content/images/2023/07/Remove-VM-from-VirtualBox.png" alt=""></p>',41)),s("p",null,[t[8]||(t[8]=i("現在，如果你嘗試 ",-1)),o(e,{href:"https://linuxhandbook.com/remove-files-directories/"},{default:a(()=>[...t[7]||(t[7]=[i("使用 rm 命令",-1)])]),_:1}),t[9]||(t[9]=i(" 並提升權限刪除 vmdk 文件，你可以刪除它（但這就是幻覺的開始）。",-1))]),t[32]||(t[32]=l('<p>例如，在這裏，我刪除了 <code>IF.vmdk</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm IF.vmdk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/use-rm-command-to-remove-vmdk-file.png" alt=""></p><p>現在，如果我嘗試創建一個具有相同名稱的新 vmdk 文件，則會出現錯誤，指出該文件已存在：</p><p><img src="https://itsfoss.com/content/images/2023/07/unable-to-create-vmdk-file-in-Linux--file-already-exist.png" alt=""></p><p>要刪除 vmdk 文件，首先，你必須使用以下命令取消註冊該文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo VBoxManage closemedium disk /path/to/MyDrive.vmdk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/unregister-vmdk-file-in-Linux-to-remove-it.png" alt=""></p><p>完成後，你可以使用 <code>rm</code> 命令刪除該文件，它將輕鬆刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm Filename.vmdk</span></span></code></pre></div><p>然後，如果你嘗試創建具有相同文件名的 vmdk 文件，你可以這樣做：</p><p><img src="https://itsfoss.com/content/images/2023/07/how-to-remove-the-vmdk-file-in-Linux.png" alt=""></p><p>這就行了！</p><h3 id="更多虛擬機技巧" tabindex="-1">更多虛擬機技巧 <a class="header-anchor" href="#更多虛擬機技巧" aria-label="Permalink to “更多虛擬機技巧”">​</a></h3><p>如果你正在尋找最快的 VM，可以使用 Qemu + KVM 的組合。我知道這聽起來很複雜。</p><p>但為了更簡單一些，我們製作了一份關於如何在 Ubuntu 上安裝和使用 Qemu 的專門指南，包括啓用共享文件夾、剪貼板和自動調整大小：</p>',16)),s("blockquote",null,[s("p",null,[s("strong",null,[o(e,{href:"https://itsfoss.com/qemu-ubuntu/"},{default:a(()=>[...t[10]||(t[10]=[i("如何在 Ubuntu 上安裝和使用 Qemu",-1)])]),_:1})])])]),t[33]||(t[33]=s("p",null,"我希望本指南對你有所幫助。",-1)),t[34]||(t[34]=s("p",null,[s("em",null,"（題圖：MJ/f74a3b33-2bcf-445b-8868-1dfc420f5b9d）")],-1)),t[35]||(t[35]=s("hr",null,null,-1)),s("p",null,[t[12]||(t[12]=i("via: ",-1)),o(e,{href:"https://itsfoss.com/virtualbox-boot-from-usb/"},{default:a(()=>[...t[11]||(t[11]=[i("https://itsfoss.com/virtualbox-boot-from-usb/",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=i("作者：",-1)),o(e,{href:"https://itsfoss.com/author/sagar/"},{default:a(()=>[...t[13]||(t[13]=[i("Sagar Sharma",-1)])]),_:1}),t[18]||(t[18]=i(" 選題：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[14]||(t[14]=[i("lujun9972",-1)])]),_:1}),t[19]||(t[19]=i(" 譯者：",-1)),o(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[15]||(t[15]=[i("geekpi",-1)])]),_:1}),t[20]||(t[20]=i(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=i("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[i("LCTT",-1)])]),_:1}),t[24]||(t[24]=i(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[i("Linux中國",-1)])]),_:1}),t[25]||(t[25]=i(" 榮譽推出",-1))])])}const c=n(d,[["render",m]]);export{B as __pageData,c as default};
